deeper_reasoning_1:
\section*{Claim}
The exact thermodynamic solution follows from a Perron-symmetric quotient of the full $q^2$-dimensional transfer problem.  For every integer $q\geq2$, $\beta>0$, and real $J_1,J_2$, let
\[
x=e^{\beta J_2},\qquad y=e^{\beta J_1/2},\qquad
u=xy^2,\qquad v=x+q-2,
\qquad w=\sqrt{q-1}\,y.
\]
Then the thermodynamic one-step growth factor of the frustrated chain is
\[
\lambda=\frac{u+v}{2}+\sqrt{\left(\frac{u-v}{2}\right)^2+w^2},
\qquad f=-\frac{1}{\beta}\ln\lambda.
\]

\section*{Premises}
\[
\begin{aligned}
\text{(P1)}\quad &\mathcal S=\{1,\ldots,q\},\quad q\geq2.\\
\text{(P2)}\quad &T_{\mathrm{ov}}((a,b),(a',b'))
=\delta(b,a')x^{\delta(a,b')}y^{\delta(a,b)+\delta(a',b')}.\\
\text{(P3)}\quad &T_{\mathrm{lad}}=T_{\mathrm{ov}}^2,\quad T_{\mathrm{lad}}\text{ has strictly positive entries}.\\
\text{(P4)}\quad &\text{Every permutation }\pi\text{ of }\mathcal S\text{ induces }R_\pi |a,b\rangle=|\pi(a),\pi(b)\rangle,\\
&\text{and }R_\pi T_{\mathrm{lad}}=T_{\mathrm{lad}}R_\pi.\\
\text{(P5)}\quad &\text{A positive finite matrix has a unique positive Perron eigenvector up to scale}.\\
\text{(P6)}\quad &\mathcal M=\operatorname{span}\{|\psi_1\rangle,|\psi_2\rangle\},\\
&|\psi_1\rangle=q^{-1/2}\sum_{s=1}^{q}|s,s\rangle,\qquad
|\psi_2\rangle=(q(q-1))^{-1/2}\sum_{\substack{s,t=1\\s\ne t}}^{q}|s,t\rangle.\\
\text{(P7)}\quad &T_{\mathrm{ov}}|_{\mathcal M}=T_2,
\qquad
T_2=\begin{pmatrix}u&w\\w&v\end{pmatrix}.\\
\text{(P8)}\quad &Z_{2N}=\operatorname{Tr}(T_{\mathrm{ov}}^{2N})=\operatorname{Tr}(T_{\mathrm{lad}}^N),\qquad
f=\lim_{N\to\infty}-\frac{1}{2N\beta}\ln Z_{2N}.
\end{aligned}
\]

\section*{Derivation}
Let $p$ be the Perron eigenvector of $T_{\mathrm{lad}}$, normalized by $\sum_{a,b}p_{a,b}=1$.  For every label permutation $\pi$,
\begin{align}
T_{\mathrm{lad}}(R_\pi p)&=R_\pi T_{\mathrm{lad}}p
=\rho(T_{\mathrm{lad}})R_\pi p.
\end{align}
The vector $R_\pi p$ is again strictly positive and has the same normalization, so uniqueness in (P5) gives
\begin{align}
R_\pi p=p\qquad\text{for every }\pi.
\end{align}
A vector fixed by every label permutation has one coefficient on the diagonal orbit $a=b$ and one coefficient on the off-diagonal orbit $a\ne b$.  Hence $p\in\mathcal M$.

Because $T_{\mathrm{ov}}\mathcal M\subseteq\mathcal M$, the ladder restriction is
\begin{align}
T_{\mathrm{lad}}|_{\mathcal M}
&=T_{\mathrm{ov}}^2|_{\mathcal M}
=(T_{\mathrm{ov}}|_{\mathcal M})^2
=T_2^2.
\end{align}
Since the Perron vector of $T_{\mathrm{lad}}$ lies in $\mathcal M$,
\begin{align}
\rho(T_{\mathrm{lad}})&=\rho(T_2^2).
\end{align}
The eigenvalues of $T_2$ are obtained from
\begin{align}
0&=\det\begin{pmatrix}u-r&w\\w&v-r\end{pmatrix}
=r^2-(u+v)r+(uv-w^2),
\end{align}
so
\begin{align}
r_\pm&=\frac{u+v}{2}\pm\sqrt{\left(\frac{u-v}{2}\right)^2+w^2}.
\end{align}
Let $A=(u+v)/2>0$ and $B=\sqrt{((u-v)/2)^2+w^2}>0$.  Then $r_+=A+B$ and $r_-=A-B$, so
\begin{align}
|r_-|&<r_+.
\end{align}
Thus $\rho(T_2^2)=r_+^2$ and
\begin{align}
\lim_{N\to\infty}\frac{1}{2N}\ln Z_{2N}
&=\frac{1}{2}\ln\rho(T_{\mathrm{lad}})
=\frac{1}{2}\ln(r_+^2)=\ln r_+.
\end{align}
Therefore $\lambda=r_+$ and $f=-\beta^{-1}\ln\lambda$.

\section*{Final Result}
\[
\boxed{\lambda=\frac{u+v}{2}+\sqrt{\left(\frac{u-v}{2}\right)^2+w^2},
\qquad f=-\beta^{-1}\ln\lambda.}
\]
\hfill$\blacksquare$

deeper_reasoning_3:
\section*{Claim}
For $J_2=-1$ and $k_B=1$, the zero-temperature phase table is obtained by comparing the exponential scales in the exact eigenvalue.  For $q\geq3$ the critical points are $J_1=0$ and $J_1=2$; for $q=2$ the critical points are $J_1=-2$ and $J_1=2$.  The branch labels, correlations, energies, and residual entropies are the following.
\[
\begin{array}{c|c|c|c|c|c}
q & J_1\text{ range} & \text{phase label} & C_1 & C_2 & (E_0,S_0)\\
\hline
q\geq3 & J_1<0 & \text{paramagnet avoiding the previous two spins} & 0&0&(0,\ln(q-2))\\
q\geq3 & 0<J_1<2 & \text{randomly dimerized state} & 1/2&0&(-J_1/2,\frac{1}{2}\ln(q-1))\\
q\geq3 & J_1>2 & \text{ferromagnetic mixture of uniform states} & 1&1&(-J_1+1,0)\\
q=2 & J_1<-2 & \text{antiferromagnetic state} & 0&1&(1,0)\\
q=2 & -2<J_1<2 & \text{dimerized state} & 1/2&0&(-J_1/2,0)\\
q=2 & J_1>2 & \text{ferromagnetic state} & 1&1&(-J_1+1,0)
\end{array}
\]
At the critical points,
\[
S_0(q\geq3,J_1=0)=\ln(q-1),\qquad
S_0(q\geq3,J_1=2)=\ln\left(\frac{1+\sqrt{4q-3}}{2}\right),
\]
and
\[
S_0(q=2,J_1=-2)=S_0(q=2,J_1=2)=\ln\varphi,
\qquad \varphi=\frac{1+\sqrt5}{2}.
\]

\section*{Premises}
\[
\begin{aligned}
\text{(P1)}\quad &\lambda=\frac{u+v}{2}+\sqrt{\left(\frac{u-v}{2}\right)^2+w^2}.\\
\text{(P2)}\quad &J_2=-1,
\quad u=e^{\beta(J_1-1)},\quad w=\sqrt{q-1}\,e^{\beta J_1/2},\quad v=e^{-\beta}+q-2.\\
\text{(P3)}\quad &f=-\beta^{-1}\ln\lambda.\\
\text{(P4)}\quad &\text{If }\lambda=g e^{\beta a}(1+o(1))\text{ with }g>0,\text{ then }E_0=-a\text{ and }S_0=\ln g.\\
\text{(P5)}\quad &\text{On a noncritical branch, before substituting }J_2=-1,
\quad C_1=-\partial f/\partial J_1,
\quad C_2=-\partial f/\partial J_2.\\
\text{(P6)}\quad &\text{Equivalently, if the dominant exponent is }a(J_1,J_2),\text{ then }C_i=\partial a/\partial J_i.
\end{aligned}
\]

\section*{Derivation for $q\geq3$}
For $q\geq3$, $q-2>0$, so $v=(q-2)(1+o(1))$ has exponential scale $0$.  The competing scales are
\begin{align}
a_v&=0, & a_w&=J_1/2, & a_u&=J_1-1.
\end{align}
If $J_1<0$, then $a_v$ is largest.  Therefore
\begin{align}
\lambda&=(q-2)(1+o(1)), & f&=o(1), & E_0&=0, & S_0&=\ln(q-2).
\end{align}
The dominant branch is the constant part of $v$, whose pre-substitution exponent is $a=0$.  Thus
\begin{align}
C_1&=\frac{\partial a}{\partial J_1}=0,
& C_2&=\frac{\partial a}{\partial J_2}=0.
\end{align}
This is the paramagnetic branch with no nearest-neighbor or next-nearest-neighbor matches in the ground-state constraint, equivalently a spin avoids the previous two spins.

If $0<J_1<2$, then $a_w$ is largest.  Hence
\begin{align}
\lambda&=\sqrt{q-1}\,e^{\beta J_1/2}(1+o(1)),
& f&=-J_1/2+o(1),\\
E_0&=-J_1/2,
& S_0&=\frac{1}{2}\ln(q-1).
\end{align}
The pre-substitution exponent is $a=J_1/2$, so
\begin{align}
C_1&=1/2,
& C_2&=0.
\end{align}
This is the randomly dimerized branch: half of nearest-neighbor bonds are matched, while next-nearest-neighbor matches are avoided.

If $J_1>2$, then $a_u$ is largest.  The pre-substitution exponent of $u=xy^2$ is $a=J_1+J_2$, and at $J_2=-1$ this is $J_1-1$.  Thus
\begin{align}
\lambda&=e^{\beta(J_1-1)}(1+o(1)),
& E_0&=-J_1+1,
& S_0&=0,\\
C_1&=1,
& C_2&=1.
\end{align}
This is the ferromagnetic branch, a mixture of the $q$ uniform ground states.

At $J_1=0$, the scales $a_v$ and $a_w$ tie.  The limiting block is
\begin{align}
\begin{pmatrix}0&\sqrt{q-1}\\\sqrt{q-1}&q-2\end{pmatrix},
\end{align}
whose larger eigenvalue is
\begin{align}
\frac{q-2}{2}+\sqrt{\left(\frac{q-2}{2}\right)^2+q-1}=q-1.
\end{align}
Therefore $S_0=\ln(q-1)$.  At $J_1=2$, the scales $a_u$ and $a_w$ tie.  Dividing by $e^{\beta}$ gives
\begin{align}
\begin{pmatrix}1&\sqrt{q-1}\\\sqrt{q-1}&0\end{pmatrix},
\end{align}
whose larger eigenvalue is $(1+\sqrt{4q-3})/2$.  Therefore
\begin{align}
S_0&=\ln\left(\frac{1+\sqrt{4q-3}}{2}\right).
\end{align}

\section*{Derivation for $q=2$}
For $q=2$, the constant part of $v$ disappears and
\begin{align}
u&=e^{\beta(J_1-1)}, & w&=e^{\beta J_1/2}, & v&=e^{-\beta}.
\end{align}
The scales are
\begin{align}
a_u&=J_1-1, & a_w&=J_1/2, & a_v&=-1.
\end{align}
If $J_1<-2$, then $a_v$ is largest.  The pre-substitution exponent is $a=J_2$, hence
\begin{align}
\lambda&=e^{-\beta}(1+o(1)),
& E_0&=1,
& S_0&=0,
& C_1&=0,
& C_2&=1.
\end{align}
This is the antiferromagnetic branch.  If $-2<J_1<2$, then $a_w$ is largest, giving
\begin{align}
\lambda&=e^{\beta J_1/2}(1+o(1)),
& E_0&=-J_1/2,
& S_0&=0,
& C_1&=1/2,
& C_2&=0,
\end{align}
which is the dimerized branch.  If $J_1>2$, then $a_u$ is largest, giving
\begin{align}
\lambda&=e^{\beta(J_1-1)}(1+o(1)),
& E_0&=-J_1+1,
& S_0&=0,
& C_1&=1,
& C_2&=1,
\end{align}
which is the ferromagnetic branch.

At $J_1=-2$, $a_w=a_v=-1$.  After scaling by $e^{-\beta}$, the limiting block is
\begin{align}
\begin{pmatrix}0&1\\1&1\end{pmatrix},
\end{align}
whose larger eigenvalue is $\varphi=(1+\sqrt5)/2$.  At $J_1=2$, $a_u=a_w=1$, and after scaling by $e^{\beta}$ the limiting block is
\begin{align}
\begin{pmatrix}1&1\\1&0\end{pmatrix},
\end{align}
whose larger eigenvalue is again $\varphi$.  Thus both $q=2$ critical points have residual entropy $\ln\varphi$.

\section*{Final Result}
The displayed table gives the required phase labels, $C_1$, $C_2$, $E_0$, and $S_0$ on every open zero-temperature branch, and the displayed critical-point limits give the required residual entropies at $J_1=0,2$ for $q\geq3$ and at $J_1=-2,2$ for $q=2$.
\hfill$\blacksquare$

deeper_reasoning_4:
\section*{Claim}
The residual entropies in the zero-temperature table have a direct ground-state counting interpretation.  For $q\geq3$, the paramagnetic branch has $S_0=\ln(q-2)$, the randomly dimerized branch has $S_0=\frac{1}{2}\ln(q-1)$, and the ferromagnetic branch has $S_0=0$.  The critical residual entropies are the Perron logarithms of the tied limiting transfer blocks.  For $q=2$, all open branches have zero residual entropy and the two critical points have $S_0=\ln\varphi$.

\section*{Premises}
\[
\begin{aligned}
\text{(P1)}\quad &S_0=\lim_{n\to\infty}n^{-1}\ln A_n\text{ when }A_n\text{ is the number of admissible ground-state words}.\\
\text{(P2)}\quad &\text{Polynomial or constant prefactors in }A_n\text{ do not affect }S_0.\\
\text{(P3)}\quad &\text{For a finite adjacency matrix }B\text{ with Perron eigenvalue }\rho(B),
\lim_{n\to\infty}n^{-1}\ln\operatorname{Tr}(B^n)=\ln\rho(B).
\end{aligned}
\]

\section*{Counting the open branches for $q\geq3$}
In the paramagnetic branch, the ground-state rule is that each new spin differs from the previous two spins.  For an open word of length $n\geq3$, the first spin has $q$ choices, the second has $q-1$ choices, and each later spin has $q-2$ choices.  Hence
\begin{align}
A_n^{P}&=q(q-1)(q-2)^{n-2},\\
\lim_{n\to\infty}\frac{1}{n}\ln A_n^{P}&=\ln(q-2).
\end{align}
Thus $S_0^P=\ln(q-2)$.

In the randomly dimerized branch, spins form equal neighboring pairs while consecutive pairs must have different colors.  For $2N$ spins, there are $N$ color blocks.  The first block has $q$ choices and each later block has $q-1$ choices, up to boundary factors that are subexponential.  Therefore
\begin{align}
A_{2N}^{D}&=q(q-1)^{N-1}\times e^{o(N)},\\
\lim_{N\to\infty}\frac{1}{2N}\ln A_{2N}^{D}&=\frac{1}{2}\ln(q-1).
\end{align}
Thus $S_0^D=\frac{1}{2}\ln(q-1)$.

In the ferromagnetic branch, the admissible ground states are the $q$ uniform words.  Hence
\begin{align}
A_n^F&=q,
& \lim_{n\to\infty}\frac{1}{n}\ln A_n^F&=0,
\end{align}
so $S_0^F=0$.

\section*{Critical points and the $q=2$ exception}
At $q\geq3$ and $J_1=0$, the tied limiting block is
\begin{align}
B_0&=\begin{pmatrix}0&\sqrt{q-1}\\\sqrt{q-1}&q-2\end{pmatrix}.
\end{align}
Its Perron eigenvalue is
\begin{align}
\rho(B_0)&=q-1,
\end{align}
so $S_0(J_1=0)=\ln(q-1)$.  At $q\geq3$ and $J_1=2$, the tied limiting block is
\begin{align}
B_2&=\begin{pmatrix}1&\sqrt{q-1}\\\sqrt{q-1}&0\end{pmatrix},
\end{align}
with
\begin{align}
\rho(B_2)&=\frac{1+\sqrt{4q-3}}{2}.
\end{align}
Thus
\begin{align}
S_0(J_1=2)&=\ln\left(\frac{1+\sqrt{4q-3}}{2}\right).
\end{align}
For $q=2$, the paramagnetic open branch has only the alternating words, the dimerized branch has only a finite choice of dimer pattern and colors, and the ferromagnetic branch has two uniform words.  Each count is subexponential, so every open $q=2$ branch has $S_0=0$.  At $J_1=-2$ and $J_1=2$, the tied limiting blocks have Perron eigenvalue
\begin{align}
\varphi&=\frac{1+\sqrt5}{2},
\end{align}
so the two critical residual entropies are $\ln\varphi$.

\section*{Final Result}
\[
\boxed{S_0^P=\ln(q-2),\qquad S_0^D=\frac{1}{2}\ln(q-1),\qquad S_0^F=0,}
\]
with the critical residual entropies obtained from the Perron eigenvalues of $B_0$, $B_2$, and the two golden-ratio $q=2$ limiting blocks.
\hfill$\blacksquare$

deeper_reasoning_5:
\section*{Claim}
For every integer $q\geq3$, the critical-point residual-entropy excesses are positive but vanish as $q\to\infty$:
\[
\Delta_0(q)=\ln(q-1)-\ln(q-2)>0,
\qquad
\Delta_2(q)=\ln\left(\frac{1+\sqrt{4q-3}}{2}\right)-\frac{1}{2}\ln(q-1)>0,
\]
and
\[
\lim_{q\to\infty}\Delta_0(q)=\lim_{q\to\infty}\Delta_2(q)=0.
\]
In the controlled large-$q$ low-temperature sector approximation, not as an exact finite-temperature phase-boundary claim, the sector crossings satisfy
\[
k_BT_{F\to D}=\frac{J_1+2J_2}{\ln(q-1)},
\qquad
k_BT_{D\to P}=\frac{J_1}{2\ln(q-2)-\ln(q-1)}.
\]

\section*{Premises}
\[
\begin{aligned}
\text{(P1)}\quad &q\geq3.\\
\text{(P2)}\quad &S_0(J_1<0)=\ln(q-2),\quad S_0(J_1=0)=\ln(q-1).\\
\text{(P3)}\quad &S_0(0<J_1<2)=\frac{1}{2}\ln(q-1),\quad
S_0(J_1=2)=\ln\left(\frac{1+\sqrt{4q-3}}{2}\right).\\
\text{(P4)}\quad &\text{In the low-temperature sector approximation, }F=E-k_BT S.\\
\text{(P5)}\quad &E_F=-J_1-J_2,\\ S_F=0,\quad
E_D=-J_1/2,\\ S_D=\frac{1}{2}\ln(q-1),\\
& E_P=0,\\ S_P=\ln(q-2).
\end{aligned}
\]

\section*{Residual-entropy excess}
From (P2),
\begin{align}
\Delta_0(q)&=\ln\left(\frac{q-1}{q-2}\right)>0,
\end{align}
because $q-1>q-2>0$.  Moreover,
\begin{align}
\lim_{q\to\infty}\Delta_0(q)
&=\lim_{q\to\infty}\ln\left(1+\frac{1}{q-2}\right)=0.
\end{align}
From (P3),
\begin{align}
\Delta_2(q)
&=\ln\left(\frac{1+\sqrt{4q-3}}{2\sqrt{q-1}}\right).
\end{align}
The logarithm is positive because
\begin{align}
1+
\sqrt{4q-3}&>\sqrt{4q-3}>\sqrt{4q-4}=2\sqrt{q-1}.
\end{align}
Thus $\Delta_2(q)>0$.  For the limit,
\begin{align}
\frac{1+\sqrt{4q-3}}{2\sqrt{q-1}}
&=\frac{1}{2\sqrt{q-1}}+\sqrt{\frac{4q-3}{4q-4}}
\longrightarrow 0+1=1,
\end{align}
so
\begin{align}
\lim_{q\to\infty}\Delta_2(q)&=\ln 1=0.
\end{align}
This proves the residual-entropy mechanism: finite $q$ has positive critical-point entropy excess, while the excess disappears as $q$ grows.

\section*{Controlled low-temperature sector comparison}
Using (P4) and (P5),
\begin{align}
F_F&=-J_1-J_2,\\
F_D&=-J_1/2-\frac{1}{2}k_BT\ln(q-1),\\
F_P&=-k_BT\ln(q-2).
\end{align}
Solving $F_F=F_D$ gives
\begin{align}
-J_1-J_2&=-J_1/2-\frac{1}{2}k_BT\ln(q-1),\\
k_BT_{F\to D}&=\frac{J_1+2J_2}{\ln(q-1)}.
\end{align}
Solving $F_D=F_P$ gives
\begin{align}
-J_1/2-\frac{1}{2}k_BT\ln(q-1)&=-k_BT\ln(q-2),\\
k_BT_{D\to P}&=\frac{J_1}{2\ln(q-2)-\ln(q-1)}.
\end{align}
For large $q$,
\begin{align}
\ln(q-1)&=\ln q+O(1/q),\\
2\ln(q-2)-\ln(q-1)&=\ln q+O(1/q).
\end{align}
Therefore
\begin{align}
k_BT_{F\to D}&=\frac{J_1+2J_2}{\ln q}\left(1+O\left(\frac{1}{q\ln q}\right)\right),\\
k_BT_{D\to P}&=\frac{J_1}{\ln q}\left(1+O\left(\frac{1}{q\ln q}\right)\right).
\end{align}
The approximation is subordinate to the entropy-gap result: it explains how the dimerized sector is selected by entropy at finite $q$ without asserting an exact finite-temperature transition line.

\section*{Final Result}
\[
\boxed{\Delta_0(q)>0,
\quad \Delta_2(q)>0,
\quad \Delta_0(q)\to0,
\quad \Delta_2(q)\to0,}
\]
and the displayed sector-crossing formulae are controlled large-$q$ low-temperature estimates only.
\hfill$\blacksquare$
